  1→import debug from "debug"
  2→import { DocHandle } from "../DocHandle.js"
  3→import { parseAutomergeUrl } from "../AutomergeUrl.js"
  4→import { Repo } from "../Repo.js"
  5→import { DocMessage } from "../network/messages.js"
  6→import { AutomergeUrl, DocumentId, PeerId } from "../types.js"
  7→import { DocSynchronizer } from "./DocSynchronizer.js"
  8→import { Synchronizer } from "./Synchronizer.js"
  9→
 10→const log = debug("automerge-repo:collectionsync")
 11→
 12→/** A CollectionSynchronizer is responsible for synchronizing a DocCollection with peers. */
 13→export class CollectionSynchronizer extends Synchronizer {
 14→  /** The set of peers we are connected with */
 15→  #peers: Set<PeerId> = new Set()
 16→
 17→  /** A map of documentIds to their synchronizers */
 18→  /** @hidden */
 19→  docSynchronizers: Record<DocumentId, DocSynchronizer> = {}
 20→
 21→  /** Used to determine if the document is know to the Collection and a synchronizer exists or is being set up */
 22→  #docSetUp: Record<DocumentId, boolean> = {}
 23→
 24→  #denylist: DocumentId[]
 25→  #hasRequested: Map<DocumentId, Set<PeerId>> = new Map()
 26→
 27→  constructor(private repo: Repo, denylist: AutomergeUrl[] = []) {
 28→    super()
 29→    this.#denylist = denylist.map(url => parseAutomergeUrl(url).documentId)
 30→  }
 31→
 32→  /** Returns a synchronizer for the given document, creating one if it doesn't already exist.  */
 33→  #fetchDocSynchronizer(handle: DocHandle<unknown>) {
 34→    if (!this.docSynchronizers[handle.documentId]) {
 35→      this.docSynchronizers[handle.documentId] =
 36→        this.#initDocSynchronizer(handle)
 37→    }
 38→    return this.docSynchronizers[handle.documentId]
 39→  }
 40→
 41→  /** Creates a new docSynchronizer and sets it up to propagate messages */
 42→  #initDocSynchronizer(handle: DocHandle<unknown>): DocSynchronizer {
 43→    const docSynchronizer = new DocSynchronizer({
 44→      handle,
 45→      peerId: this.repo.networkSubsystem.peerId,
 46→      onLoadSyncState: async peerId => {
 47→        if (!this.repo.storageSubsystem) {
 48→          return
 49→        }
 50→
 51→        const { storageId, isEphemeral } =
 52→          this.repo.peerMetadataByPeerId[peerId] || {}
 53→        if (!storageId || isEphemeral) {
 54→          return
 55→        }
 56→
 57→        return this.repo.storageSubsystem.loadSyncState(
 58→          handle.documentId,
 59→          storageId
 60→        )
 61→      },
 62→    })
 63→    docSynchronizer.on("message", event => this.emit("message", event))
 64→    docSynchronizer.on("open-doc", event => this.emit("open-doc", event))
 65→    docSynchronizer.on("sync-state", event => this.emit("sync-state", event))
 66→    docSynchronizer.on("metrics", event => this.emit("metrics", event))
 67→    return docSynchronizer
 68→  }
 69→
 70→  /** returns an array of peerIds that we share this document generously with */
 71→  async #documentGenerousPeers(documentId: DocumentId): Promise<PeerId[]> {
 72→    const peers = Array.from(this.#peers)
 73→    const generousPeers: PeerId[] = []
 74→    for (const peerId of peers) {
 75→      const okToShare = await this.#shouldShare(peerId, documentId)
 76→      if (okToShare) generousPeers.push(peerId)
 77→    }
 78→    return generousPeers
 79→  }
 80→
 81→  // PUBLIC
 82→
 83→  /**
 84→   * When we receive a sync message for a document we haven't got in memory, we
 85→   * register it with the repo and start synchronizing
 86→   */
 87→  async receiveMessage(message: DocMessage) {
 88→    log(
 89→      `onSyncMessage: ${message.senderId}, ${message.documentId}, ${
 90→        "data" in message ? message.data.byteLength + "bytes" : ""
 91→      }`
 92→    )
 93→
 94→    const documentId = message.documentId
 95→    if (!documentId) {
 96→      throw new Error("received a message with an invalid documentId")
 97→    }
 98→
 99→    if (this.#denylist.includes(documentId)) {
100→      this.emit("metrics", {
101→        type: "doc-denied",
102→        documentId,
103→      })
104→      this.emit("message", {
105→        type: "doc-unavailable",
106→        documentId,
107→        targetId: message.senderId,
108→      })
109→      return
110→    }
111→
112→    // Record the request so that even if access is denied now, we know that the
113→    // peer requested the document so that if the share policy changes we know
114→    // to begin syncing with this peer
115→    if (message.type === "request" || message.type === "sync") {
116→      if (!this.#hasRequested.has(documentId)) {
117→        this.#hasRequested.set(documentId, new Set())
118→      }
119→      this.#hasRequested.get(documentId)?.add(message.senderId)
120→    }
121→
122→    const hasAccess = await this.repo.shareConfig.access(
123→      message.senderId,
124→      documentId
125→    )
126→    if (!hasAccess) {
127→      log("access denied")
128→      this.emit("message", {
129→        type: "doc-unavailable",
130→        documentId,
131→        targetId: message.senderId,
132→      })
133→      return
134→    }
135→
136→    this.#docSetUp[documentId] = true
137→
138→    const handle = await this.repo.find(documentId, {
139→      allowableStates: ["ready", "unavailable", "requesting"],
140→    })
141→    const docSynchronizer = this.#fetchDocSynchronizer(handle)
142→
143→    docSynchronizer.receiveMessage(message)
144→
145→    // Initiate sync with any new peers
146→    const peers = await this.#documentGenerousPeers(documentId)
147→    void docSynchronizer.beginSync(
148→      peers.filter(peerId => !docSynchronizer.hasPeer(peerId))
149→    )
150→  }
151→
152→  /**
153→   * Starts synchronizing the given document with all peers that we share it generously with.
154→   */
155→  addDocument(handle: DocHandle<unknown>) {
156→    // HACK: this is a hack to prevent us from adding the same document twice
157→    if (this.#docSetUp[handle.documentId]) {
158→      return
159→    }
160→    this.#docSetUp[handle.documentId] = true
161→    const docSynchronizer = this.#fetchDocSynchronizer(handle)
162→    void this.#documentGenerousPeers(handle.documentId).then(peers => {
163→      void docSynchronizer.beginSync(peers)
164→    })
165→  }
166→
167→  /** Removes a document and stops synchronizing them */
168→  removeDocument(documentId: DocumentId) {
169→    log(`removing document ${documentId}`)
170→    const docSynchronizer = this.docSynchronizers[documentId]
171→    if (docSynchronizer !== undefined) {
172→      this.peers.forEach(peerId => docSynchronizer.endSync(peerId))
173→    }
174→    delete this.docSynchronizers[documentId]
175→    delete this.#docSetUp[documentId]
176→  }
177→
178→  /** Adds a peer and maybe starts synchronizing with them */
179→  addPeer(peerId: PeerId) {
180→    log(`adding ${peerId} & synchronizing with them`)
181→
182→    if (this.#peers.has(peerId)) {
183→      return
184→    }
185→
186→    this.#peers.add(peerId)
187→    for (const docSynchronizer of Object.values(this.docSynchronizers)) {
188→      const { documentId } = docSynchronizer
189→      void this.#shouldShare(peerId, documentId).then(okToShare => {
190→        if (okToShare) void docSynchronizer.beginSync([peerId])
191→      })
192→    }
193→  }
194→
195→  /** Removes a peer and stops synchronizing with them */
196→  removePeer(peerId: PeerId) {
197→    log(`removing peer ${peerId}`)
198→    this.#peers.delete(peerId)
199→    for (const requested of this.#hasRequested.values()) {
200→      requested.delete(peerId)
201→    }
202→
203→    for (const docSynchronizer of Object.values(this.docSynchronizers)) {
204→      docSynchronizer.endSync(peerId)
205→    }
206→  }
207→
208→  /** Returns a list of all connected peer ids */
209→  get peers(): PeerId[] {
210→    return Array.from(this.#peers)
211→  }
212→
213→  /**
214→   * Re-evaluates share policy for a document and updates sync accordingly
215→   *
216→   * @remarks
217→   * This is called when the share policy for a document has changed. It re-evaluates
218→   * which peers should have access and starts/stops synchronization as needed.
219→   */
220→  async reevaluateDocumentShare() {
221→    const peers = Array.from(this.#peers)
222→    const docPromises = []
223→    for (const docSynchronizer of Object.values(this.docSynchronizers)) {
224→      const documentId = docSynchronizer.documentId
225→      docPromises.push(
226→        (async () => {
227→          for (const peerId of peers) {
228→            const shouldShare = await this.#shouldShare(peerId, documentId)
229→            const isAlreadySyncing = docSynchronizer.hasPeer(peerId)
230→
231→            log(
232→              `reevaluateDocumentShare: ${peerId} for ${documentId}, shouldShare: ${shouldShare}, isAlreadySyncing: ${isAlreadySyncing}`
233→            )
234→            if (shouldShare && !isAlreadySyncing) {
235→              log(
236→                `reevaluateDocumentShare: starting sync with ${peerId} for ${documentId}`
237→              )
238→              void docSynchronizer.beginSync([peerId])
239→            } else if (!shouldShare && isAlreadySyncing) {
240→              log(
241→                `reevaluateDocumentShare: stopping sync with ${peerId} for ${documentId}`
242→              )
243→              docSynchronizer.endSync(peerId)
244→            }
245→          }
246→        })().catch(e => {
247→          console.log(
248→            `error reevaluating document share for ${documentId}: ${e}`
249→          )
250→        })
251→      )
252→    }
253→    await Promise.allSettled(docPromises)
254→  }
255→
256→  metrics(): {
257→    [key: string]: {
258→      peers: PeerId[]
259→      size: { numOps: number; numChanges: number }
260→    }
261→  } {
262→    return Object.fromEntries(
263→      Object.entries(this.docSynchronizers).map(
264→        ([documentId, synchronizer]) => {
265→          return [documentId, synchronizer.metrics()]
266→        }
267→      )
268→    )
269→  }
270→
271→  async #shouldShare(peerId: PeerId, documentId: DocumentId): Promise<boolean> {
272→    const [announce, access] = await Promise.all([
273→      this.repo.shareConfig.announce(peerId, documentId),
274→      this.repo.shareConfig.access(peerId, documentId),
275→    ])
276→    const hasRequested =
277→      this.#hasRequested.get(documentId)?.has(peerId) ?? false
278→    return announce || (access && hasRequested)
279→  }
280→}
