  1→import debug from "debug"
  2→import { EventEmitter } from "eventemitter3"
  3→import { PeerId, SessionId } from "../types.js"
  4→import type {
  5→  NetworkAdapterInterface,
  6→  PeerDisconnectedPayload,
  7→  PeerMetadata,
  8→} from "./NetworkAdapterInterface.js"
  9→import {
 10→  EphemeralMessage,
 11→  MessageContents,
 12→  RepoMessage,
 13→  isEphemeralMessage,
 14→  isRepoMessage,
 15→} from "./messages.js"
 16→
 17→type EphemeralMessageSource = `${PeerId}:${SessionId}`
 18→
 19→const getEphemeralMessageSource = (message: EphemeralMessage) =>
 20→  `${message.senderId}:${message.sessionId}` as EphemeralMessageSource
 21→
 22→export class NetworkSubsystem extends EventEmitter<NetworkSubsystemEvents> {
 23→  #log: debug.Debugger
 24→  #adaptersByPeer: Record<PeerId, NetworkAdapterInterface> = {}
 25→
 26→  #count = 0
 27→  #sessionId: SessionId = Math.random().toString(36).slice(2) as SessionId
 28→  #ephemeralSessionCounts: Record<EphemeralMessageSource, number> = {}
 29→  adapters: NetworkAdapterInterface[] = []
 30→
 31→  constructor(
 32→    adapters: NetworkAdapterInterface[],
 33→    public peerId: PeerId,
 34→    private peerMetadata: Promise<PeerMetadata>
 35→  ) {
 36→    super()
 37→    this.#log = debug(`automerge-repo:network:${this.peerId}`)
 38→    adapters.forEach(a => this.addNetworkAdapter(a))
 39→  }
 40→
 41→  disconnect() {
 42→    this.adapters.forEach(a => a.disconnect())
 43→  }
 44→
 45→  reconnect() {
 46→    this.adapters.forEach(a => a.connect(this.peerId))
 47→  }
 48→
 49→  addNetworkAdapter(networkAdapter: NetworkAdapterInterface) {
 50→    this.adapters.push(networkAdapter)
 51→
 52→    networkAdapter.on("peer-candidate", ({ peerId, peerMetadata }) => {
 53→      this.#log(`peer candidate: ${peerId} `)
 54→      // TODO: This is where authentication would happen
 55→
 56→      // TODO: on reconnection, this would create problems!
 57→      // the server would see a reconnection as a late-arriving channel
 58→      // for an existing peer and decide to ignore it until the connection
 59→      // times out: turns out my ICE/SIP emulation laziness did not pay off here
 60→      if (!this.#adaptersByPeer[peerId]) {
 61→        // TODO: handle losing a server here
 62→        this.#adaptersByPeer[peerId] = networkAdapter
 63→      }
 64→
 65→      this.emit("peer", { peerId, peerMetadata })
 66→    })
 67→
 68→    networkAdapter.on("peer-disconnected", ({ peerId }) => {
 69→      this.#log(`peer disconnected: ${peerId} `)
 70→      delete this.#adaptersByPeer[peerId]
 71→      this.emit("peer-disconnected", { peerId })
 72→    })
 73→
 74→    networkAdapter.on("message", msg => {
 75→      if (!isRepoMessage(msg)) {
 76→        this.#log(`invalid message: ${JSON.stringify(msg)}`)
 77→        return
 78→      }
 79→
 80→      this.#log(`message from ${msg.senderId}`)
 81→
 82→      if (isEphemeralMessage(msg)) {
 83→        const source = getEphemeralMessageSource(msg)
 84→        if (
 85→          this.#ephemeralSessionCounts[source] === undefined ||
 86→          msg.count > this.#ephemeralSessionCounts[source]
 87→        ) {
 88→          this.#ephemeralSessionCounts[source] = msg.count
 89→          this.emit("message", msg)
 90→        }
 91→
 92→        return
 93→      }
 94→
 95→      this.emit("message", msg)
 96→    })
 97→
 98→    networkAdapter.on("close", () => {
 99→      this.#log("adapter closed")
100→      Object.entries(this.#adaptersByPeer).forEach(([peerId, other]) => {
101→        if (other === networkAdapter) {
102→          delete this.#adaptersByPeer[peerId as PeerId]
103→        }
104→      })
105→      this.adapters = this.adapters.filter(a => a !== networkAdapter)
106→    })
107→
108→    this.peerMetadata
109→      .then(peerMetadata => {
110→        networkAdapter.connect(this.peerId, peerMetadata)
111→      })
112→      .catch(err => {
113→        this.#log("error connecting to network", err)
114→      })
115→  }
116→
117→  // TODO: this probably introduces a race condition for the ready event
118→  // but I plan to refactor that as part of this branch in another patch
119→  removeNetworkAdapter(networkAdapter: NetworkAdapterInterface) {
120→    this.adapters = this.adapters.filter(a => a !== networkAdapter)
121→    networkAdapter.disconnect()
122→  }
123→
124→  send(message: MessageContents) {
125→    const peer = this.#adaptersByPeer[message.targetId]
126→    if (!peer) {
127→      this.#log(`Tried to send message but peer not found: ${message.targetId}`)
128→      return
129→    }
130→
131→    /** Messages come in without a senderId and other required information; this is where we make
132→     * sure they have everything they need.
133→     */
134→    const prepareMessage = (message: MessageContents): RepoMessage => {
135→      if (message.type === "ephemeral") {
136→        if ("count" in message) {
137→          // existing ephemeral message from another peer; pass on without changes
138→          return message as EphemeralMessage
139→        } else {
140→          // new ephemeral message from us; add our senderId as well as a counter and session id
141→          return {
142→            ...message,
143→            count: ++this.#count,
144→            sessionId: this.#sessionId,
145→            senderId: this.peerId,
146→          } as EphemeralMessage
147→        }
148→      } else {
149→        // other message type; just add our senderId
150→        return {
151→          ...message,
152→          senderId: this.peerId,
153→        } as RepoMessage
154→      }
155→    }
156→
157→    const outbound = prepareMessage(message)
158→    this.#log("sending message %o", outbound)
159→    peer.send(outbound as RepoMessage)
160→  }
161→
162→  isReady = () => {
163→    return this.adapters.every(a => a.isReady())
164→  }
165→
166→  whenReady = async () => {
167→    return Promise.all(this.adapters.map(a => a.whenReady()))
168→  }
169→}
170→
171→// events & payloads
172→
173→export interface NetworkSubsystemEvents {
174→  peer: (payload: PeerPayload) => void
175→  "peer-disconnected": (payload: PeerDisconnectedPayload) => void
176→  message: (payload: RepoMessage) => void
177→}
178→
179→export interface PeerPayload {
180→  peerId: PeerId
181→  peerMetadata: PeerMetadata
182→}
