 17→public partial class EditorWindow : Window
 18→{
 19→  readonly ILogger<EditorWindow> _logger;
 20→  DocumentSessionDialogViewModel? _sessionVm;
 21→  ConnectionStatusBarViewModel? _statusBarVm;
 22→
 23→  public EditorWindow()
 24→  {
 25→    var loggerFactory = App.Services?.GetService<ILoggerFactory>();
 26→    _logger = (loggerFactory ?? NullLoggerFactory.Instance).CreateLogger<EditorWindow>();
 27→    InitializeComponent();
 28→    Loaded += OnLoaded;
 29→  }
 30→
 31→  async void OnLoaded(object? sender, EventArgs e)
 32→  {
 33→    _sessionVm = new DocumentSessionDialogViewModel();
 34→    _sessionVm.ResultReady += OnSessionResultReady;
 35→
 36→    SessionDialog.DataContext = _sessionVm;
 37→    SessionDialog.RefreshRequested += OnRefreshRequested;
 38→
 39→    _statusBarVm = new ConnectionStatusBarViewModel();
 40→    StatusBar.DataContext = _statusBarVm;
 41→
 42→    // Track caret position and selection changes from the TextBox
 43→    LocalEditor.PropertyChanged += (_, args) =>
 44→    {
 45→      if(DataContext is not EditorViewModel vm)
 46→      {
 47→        return;
 48→      }
 49→
 50→      if(args.Property == TextBox.CaretIndexProperty)
 51→      {
 52→        vm.CursorPosition = LocalEditor.CaretIndex;
 53→      }
 54→
 55→      if(args.Property == TextBox.SelectionStartProperty || args.Property == TextBox.SelectionEndProperty)
 56→      {
 57→        int start = LocalEditor.SelectionStart;
 58→        int end = LocalEditor.SelectionEnd;
 59→        vm.SelectionLength = Math.Abs(end - start);
 60→      }
 61→    };
 62→
 63→    // Load stored documents, initialize connection, then fetch server documents
 64→    if(DataContext is EditorViewModel vm2 && vm2.RepoService is not null)
 65→    {
 66→      _sessionVm.LoadStoredDocuments(vm2.RepoService.StorageDirectory);
 67→      await vm2.RepoService.InitializeAsync();
 68→      WireConnectionEvents(vm2.RepoService);
 69→      await _sessionVm.LoadServerDocumentsAsync(vm2.RepoService);
 70→    }
 71→  }
 72→
 73→  async void OnRefreshRequested(object? sender, EventArgs e)
 74→  {
 75→    if(_sessionVm is null || DataContext is not EditorViewModel vm || vm.RepoService is null)
 76→    {
 77→      return;
 78→    }
 79→
 80→    await _sessionVm.LoadServerDocumentsAsync(vm.RepoService);
 81→  }
 82→
 83→  async void OnSessionResultReady(object? sender, EventArgs e)
 84→  {
 85→    if(_sessionVm?.Result is null || DataContext is not EditorViewModel vm)
 86→    {
 87→      return;
 88→    }
 89→
 90→    var result = _sessionVm.Result;
 91→    _sessionVm.IsLoading = true;
 92→    _sessionVm.ErrorMessage = null;
 93→
 94→    try
 95→    {
 96→      switch(result.Action)
 97→      {
 98→        case SessionAction.Create:
 99→          await HandleCreateAsync(vm);
100→          break;
101→        case SessionAction.Join:
102→          await HandleJoinAsync(vm, result.DocumentId!);
103→          break;
104→        case SessionAction.Resume:
105→          await HandleResumeAsync(vm, result.DocumentId!);
106→          break;
107→      }
108→
109→      await Dispatcher.UIThread.InvokeAsync(() => _sessionVm.IsLoading = false);
110→    }
111→    catch(OperationCanceledException ex)
112→    {
113→      _logger.LogWarning(ex, "Document {Action} was cancelled", result.Action);
114→      await Dispatcher.UIThread.InvokeAsync(() =>
115→      {
116→        vm.SyncStatus = "Operation cancelled";
117→        _sessionVm.IsLoading = false;
118→      });
119→    }
120→    catch(TimeoutException ex)
121→    {
122→      _logger.LogWarning(ex, "Document {Action} timed out", result.Action);
123→      await Dispatcher.UIThread.InvokeAsync(() =>
124→      {
125→        vm.SyncStatus = "Operation timed out";
126→        _sessionVm.ErrorMessage = "The operation timed out. The document may be unavailable or the server is not responding.";
127→        _sessionVm.IsLoading = false;
128→      });
129→    }
130→    catch(Exception ex)
131→    {
132→      _logger.LogWarning(ex, "Document {Action} failed", result.Action);
133→      await Dispatcher.UIThread.InvokeAsync(() =>
134→      {
135→        vm.SyncStatus = $"Error: {ex.Message}";
136→        _sessionVm.ErrorMessage = ex.Message;
137→        _sessionVm.IsLoading = false;
138→      });
139→    }
140→  }
141→
142→  async Task HandleCreateAsync(EditorViewModel vm)
143→  {
144→    if(vm.RepoService is null)
145→    {
146→      _logger.LogInformation("Creating offline document (no RepoService)");
147→      var automergeService = new AutomergeService();
148→      await Dispatcher.UIThread.InvokeAsync(() => vm.SetAutomergeService(automergeService));
149→      await ShowEditorAsync(null);
150→      return;
151→    }
152→
153→    await vm.RepoService.InitializeAsync();
154→    WireConnectionEvents(vm.RepoService);
155→
156→    var handle = await vm.RepoService.Repo!.Create<object>();
157→
158→    handle.Change(doc =>
159→    {
160→      doc.PutObject(doc.RootId, "content", AutomergeContainerType.Text);
161→    }, "Initialize text field");
162→
163→    var document = ((IDocHandle)handle).GetDocument()!;
164→    var automerge = AutomergeService.FromDocument(document);
165→    await Dispatcher.UIThread.InvokeAsync(() =>
166→    {
167→      vm.SetAutomergeService(automerge);
168→      vm.DocHandle = handle;
169→    });
170→
171→    _logger.LogInformation("Created document {DocumentId}", handle.DocumentId);
172→    await ShowEditorAsync(handle.DocumentId.ToString());
173→  }
174→
175→  async Task HandleJoinAsync(EditorViewModel vm, string documentId)
176→  {
177→    if(vm.RepoService is null)
178→    {
179→      _logger.LogWarning("Cannot join document {DocumentId}: no server connection", documentId);
180→      await Dispatcher.UIThread.InvokeAsync(() =>
181→        _sessionVm!.ErrorMessage = "Cannot join: no server connection");
182→      return;
183→    }
184→
185→    await vm.RepoService.InitializeAsync();
186→    WireConnectionEvents(vm.RepoService);
187→
188→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Joining document...");
189→
190→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(30));
191→    if(handle is null)
192→    {
193→      _logger.LogWarning("Join failed: document {DocumentId} not found", documentId);
194→      await Dispatcher.UIThread.InvokeAsync(() =>
195→        _sessionVm!.ErrorMessage = "Document not found");
196→      return;
197→    }
198→
199→    await handle.WhenReadyAsync().WaitAsync(TimeSpan.FromSeconds(30));
200→
201→    var document = ((IDocHandle)handle).GetDocument()!;
202→    var automerge = AutomergeService.FromDocument(document);
203→    await Dispatcher.UIThread.InvokeAsync(() =>
204→    {
205→      vm.SetAutomergeService(automerge);
206→      vm.DocHandle = handle;
207→    });
208→
209→    _logger.LogInformation("Joined document {DocumentId}", handle.DocumentId);
210→    await ShowEditorAsync(handle.DocumentId.ToString());
211→  }
212→
213→  async Task HandleResumeAsync(EditorViewModel vm, string documentId)
214→  {
215→    if(vm.RepoService is null)
216→    {
217→      _logger.LogWarning("Cannot resume document {DocumentId}: no server connection", documentId);
218→      await Dispatcher.UIThread.InvokeAsync(() =>
219→        _sessionVm!.ErrorMessage = "Cannot resume: no server connection");
220→      return;
221→    }
222→
223→    await vm.RepoService.InitializeAsync();
224→    WireConnectionEvents(vm.RepoService);
225→
226→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Resuming document...");
227→
228→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(10));
229→    if(handle is null)
230→    {
231→      _logger.LogWarning("Resume failed: document {DocumentId} not found in storage", documentId);
232→      await Dispatcher.UIThread.InvokeAsync(() =>
233→        _sessionVm!.ErrorMessage = "Document not found in storage");
234→      return;
235→    }
236→
237→    await handle.WhenReadyAsync().WaitAsync(TimeSpan.FromSeconds(30));
238→
239→    var document = ((IDocHandle)handle).GetDocument()!;
240→    var automerge = AutomergeService.FromDocument(document);
241→    await Dispatcher.UIThread.InvokeAsync(() =>
242→    {
243→      vm.SetAutomergeService(automerge);
244→      vm.DocHandle = handle;
245→    });
246→
247→    _logger.LogInformation("Resumed document {DocumentId}", handle.DocumentId);
248→    await ShowEditorAsync(handle.DocumentId.ToString());
249→  }
250→
251→  void WireConnectionEvents(RepoService repoService)
252→  {
253→    if(_statusBarVm is null)
254→    {
255→      return;
256→    }
257→
258→    _statusBarVm.PeerId = repoService.PeerId?.ToString();
259→    _statusBarVm.ServerUrl = repoService is { IsInitialized: true }
260→      ? "Connected"
261→      : "Offline";
262→
263→    // Set initial connection state (event handler below only fires on future changes)
264→    _statusBarVm.ConnectionState = repoService.ConnectionState switch
265→    {
266→      ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
267→      ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
268→      ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
269→      _ => DemoApp.Shared.ConnectionState.Disconnected
270→    };
271→
272→    repoService.ConnectionStateChanged += (_, state) =>
273→      Dispatcher.UIThread.Post(() =>
274→      {
275→        if(_statusBarVm is null)
276→        {
277→          return;
278→        }
279→
280→        _statusBarVm.ConnectionState = state switch
281→        {
282→          ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
283→          ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
284→          ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
285→          _ => DemoApp.Shared.ConnectionState.Disconnected
286→        };
287→      });
288→
289→    repoService.PeerCountChanged += (_, count) =>
290→      Dispatcher.UIThread.Post(() =>
291→      {
292→        if(_statusBarVm is not null)
293→        {
294→          _statusBarVm.PeerCount = count;
295→        }
296→      });
297→  }
298→
299→  async Task ShowEditorAsync(string? documentId)
300→  {
301→    await Dispatcher.UIThread.InvokeAsync(() =>
302→    {
303→      SessionPanel.IsVisible = false;
304→      EditorPanel.IsVisible = true;
305→
306→      if(_statusBarVm is not null)
307→      {
308→        _statusBarVm.DocumentId = documentId ?? "local";
309→      }
310→
311→      LocalEditor.Focus();
312→    });
313→  }
314→}
