217→  internal void ApplyTextChange(string newText)
218→  {
219→    if(_automergeService is null || _docHandle is null)
220→      return;
221→
222→    // Use _documentText (the UI's last-known text) instead of reading from the
223→    // native CRDT document under lock. This avoids blocking the UI thread when
224→    // a previous ChangeTextAsync is still holding the document lock.
225→    // The diff is correct because _documentText is set by RaiseAndSetIfChanged
226→    // immediately after this method returns, so each character sees the cumulative text.
227→    string currentText = _documentText;
228→
229→    // Find the difference and apply as a splice operation.
230→    // This is a simplified diff: find common prefix and suffix.
231→    int prefixLen = 0;
232→    int minLen = Math.Min(currentText.Length, newText.Length);
233→    while(prefixLen < minLen && currentText[prefixLen] == newText[prefixLen])
234→    {
235→      prefixLen++;
236→    }
237→
238→    int suffixLen = 0;
239→    int maxSuffix = minLen - prefixLen;
240→    while(suffixLen < maxSuffix
241→      && currentText[currentText.Length - 1 - suffixLen] == newText[newText.Length - 1 - suffixLen])
242→    {
243→      suffixLen++;
244→    }
245→
246→    int deleteCount = currentText.Length - prefixLen - suffixLen;
247→    string insertText = newText.Substring(prefixLen, newText.Length - prefixLen - suffixLen);
248→    bool hasChanges = deleteCount > 0 || insertText.Length > 0;
249→
250→    if(hasChanges)
251→    {
252→      _logger.LogDebug(
253→        "Text change: insert {InsertCount} chars, delete {DeleteCount} at offset {Offset}",
254→        insertText.Length, deleteCount, prefixLen);
255→      
256→      var textId = _automergeService.TextId;
257→      _ = ChangeTextAsync(textId, prefixLen, deleteCount, insertText);
258→    }
259→  }
260→
261→  async Task ChangeTextAsync(AutomergeObjectId textId, int prefixLen, int deleteCount, string insertText)
262→  {
263→    try
264→    {
265→      await _docHandle!.ChangeAsync(
266→        doc =>
267→        {
268→          SaveCursorBeforeEdit();
269→          doc.SpliceText(textId, (ulong)prefixLen, deleteCount, insertText);
270→        },
271→        $"Edit at {prefixLen}").ConfigureAwait(false);
272→    }
273→    catch(Exception ex)
274→    {
275→      _logger.LogError(ex, "Failed to apply text change at offset {Offset}", prefixLen);
276→    }
277→  }
278→
279→  internal void RefreshFromDocument()
280→  {
281→    if(_automergeService is null)
282→    {
283→      return;
284→    }
285→
286→    string text = _automergeService.GetText();
287→    if(_documentText != text)
288→    {
289→      _logger.LogDebug("Remote update: refreshing document text ({CharCount} chars)", text.Length);
290→      Interlocked.CompareExchange(ref _isRemoteUpdate, 1, 0);
291→      try
292→      {
293→        _documentText = text;
294→        this.RaisePropertyChanged(nameof(DocumentText));
295→      }
296→      finally
297→      {
298→        Interlocked.Exchange(ref _isRemoteUpdate, 0);
299→      }
300→    }
301→
302→    // Use the core variant — caller is either already holding the document lock
303→    // (OnDocHandleChanged) or no lock is needed (SetAutomergeService, no DocHandle yet).
304→    UpdateFormattingStateCore();
305→  }
306→
307→  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
308→  {
309→    if(e.IsLocal)
310→    {
311→      return;
312→    }
313→
314→    _dispatcher(() => _ = HandleRemoteChangeAsync());
315→  }
316→
317→  async Task HandleRemoteChangeAsync()
318→  {
319→    SemaphoreSlim? docLock = _docHandle is not null ? ((IDocHandle)_docHandle).DocumentLock : null;
320→    if(docLock is not null)
321→    {
322→      // Use async lock acquisition to avoid blocking the UI thread.
323→      // The synchronous WithDocumentLock(Wait()) would deadlock when the sync thread
324→      // holds _documentLock and the UI thread can't yield.
325→      await docLock.WaitAsync().ConfigureAwait(false);
326→    }
327→
328→    try
329→    {
330→      SaveCursorBeforeEdit();
331→      RefreshFromDocument();
332→      RestoreCursorAfterEdit();
333→    }
334→    finally
335→    {
336→      docLock?.Release();
337→    }
338→  }
339→
340→  void SaveCursorBeforeEdit()
341→  {
342→    if(_automergeService is null || _cursorPosition <= 0)
343→    {
344→      _savedCursor = null;
345→      return;
346→    }
347→
348→    try
349→    {
350→      ulong pos = (ulong)Math.Min(_cursorPosition, _automergeService.GetText().Length);
351→      if(pos > 0)
352→      {
353→        _savedCursor = _automergeService.GetCursor(pos - 1);
354→      }
355→      else
356→      {
357→        _savedCursor = null;
358→      }
359→    }
360→    catch(Exception ex)
361→    {
362→      _logger.LogWarning(ex, "Failed to save cursor at position {Position}", _cursorPosition);
363→      _savedCursor = null;
364→    }
365→  }
366→
367→  void RestoreCursorAfterEdit()
368→  {
369→    if(_automergeService is null || _savedCursor is null)
370→    {
371→      return;
372→    }
373→
374→    try
375→    {
376→      ulong pos = _automergeService.GetCursorPosition(_savedCursor);
377→      CursorPosition = (int)(pos + 1);
378→    }
379→    catch(Exception ex)
380→    {
381→      _logger.LogWarning(ex, "Failed to restore cursor after edit");
382→    }
383→
384→    _savedCursor = null;
385→  }
386→
387→  void ToggleBold()
388→  {
389→    if(_automergeService is null || _docHandle is null || _selectionLength <= 0)
390→    {
391→      return;
392→    }
393→
394→    ulong start = (ulong)_cursorPosition;
395→    ulong end = (ulong)(_cursorPosition + _selectionLength);
396→    var textId = _automergeService.TextId;
397→
398→    if(_isBold)
399→    {
400→      _docHandle.Change(doc => doc.Unmark(textId, "bold", start, end, ExpandMode.Both), "Unmark bold");
401→    }
402→    else
403→    {
404→      _docHandle.Change(doc => doc.Mark(textId, start, end, "bold", true, ExpandMode.Both), "Mark bold");
405→    }
406→
407→    UpdateFormattingState();
