451→    }
452→
453→    UpdateFormattingState();
454→  }
455→
456→  /// <summary>
457→  /// Updates formatting state with async document lock acquisition.
458→  /// Uses fire-and-forget async to avoid blocking the UI thread when
459→  /// the document lock is held by sync operations or pending ChangeTextAsync tasks.
460→  /// Called from CursorPosition.set, ToggleBold/Italic/Underline.
461→  /// </summary>
462→  void UpdateFormattingState()
463→  {
464→    if(_disposed || _automergeService is null)
465→      return;
466→
467→    _ = UpdateFormattingStateAsync();
468→  }
469→
470→  async Task UpdateFormattingStateAsync()
471→  {
472→    try
473→    {
474→      SemaphoreSlim? docLock = _docHandle is not null ? ((IDocHandle)_docHandle).DocumentLock : null;
475→      if(docLock is not null)
476→        await docLock.WaitAsync().ConfigureAwait(false);
477→
478→      try
479→      {
480→        UpdateFormattingStateCore();
481→      }
482→      finally
483→      {
484→        docLock?.Release();
485→      }
486→    }
487→    catch(ObjectDisposedException) when(_disposed)
488→    {
489→      // Expected during shutdown
490→    }
491→    catch(Exception ex)
492→    {
493→      _logger.LogWarning(ex, "Failed to update formatting state");
494→    }
495→  }
496→
497→  /// <summary>
498→  /// Core formatting state update — reads marks from the native document.
499→  /// Must be called either with the document lock held, or when no DocHandle
500→  /// is present (i.e. from SetAutomergeService before a collaborative session starts).
501→  /// </summary>
502→  void UpdateFormattingStateCore()
503→  {
504→    if(_disposed || _automergeService is null)
505→    {
506→      return;
507→    }
508→
509→    var marks = _automergeService.GetMarks();
510→    FormattingState state = FormattingState.FromMarks(marks, (ulong)_cursorPosition);
511→    IsBold = state.IsBold;
512→    IsItalic = state.IsItalic;
513→    IsUnderline = state.IsUnderline;
514→  }
515→
516→  void SaveDocument()
517→  {
518→    if(_automergeService is null)
519→    {
520→      SyncStatus = "No document loaded";
521→      return;
522→    }
523→
524→    byte[] saved = WithDocumentLock(() => _automergeService.Save());
525→    SyncStatus = $"Saved ({saved.Length} bytes)";
526→  }
527→
528→  void ExportJson()
529→  {
530→    if(_automergeService is null)
531→    {
532→      SyncStatus = "No document loaded";
533→      return;
534→    }
535→
536→    string json = WithDocumentLock(() => _automergeService.Document.HydrateJson());
537→    _logger.LogInformation("Document JSON: {Json}", json);
538→    SyncStatus = $"Exported JSON ({json.Length} chars)";
539→  }
540→
541→  public void Dispose()
542→  {
543→    if(!_disposed)
544→    {
545→      _disposed = true;
546→
547→      if(_docHandle is not null)
548→      {
549→        _docHandle.Changed -= OnDocHandleChanged;
550→      }
551→
552→      _automergeService?.Dispose();
553→      _repoService?.Dispose();
554→    }
555→  }
556→}
