134→  /// <summary>
135→  /// Helper that uses a real AutomergeDocument to create marks with proper AutomergeScalarValue.
136→  /// </summary>
137→  static IReadOnlyList<AutomergeMarkInfo> CreateMarks(
138→    params (string name, bool value, ulong start, ulong end)[] markSpecs)
139→  {
140→    using var doc = AutomergeDocument.Create();
141→    AutomergeObjectId textId = doc.PutObject(doc.RootId, "t", AutomergeContainerType.Text);
142→
143→    // Ensure text is long enough for all mark ranges
144→    ulong maxEnd = 0;
145→    foreach(var spec in markSpecs)
146→    {
147→      if(spec.end > maxEnd)
148→      {
149→        maxEnd = spec.end;
150→      }
151→    }
152→
153→    doc.SpliceText(textId, 0, 0, new string('x', (int)maxEnd));
154→
155→    foreach(var spec in markSpecs)
156→    {
157→      doc.Mark(textId, spec.start, spec.end, spec.name, spec.value, ExpandMode.Both);
158→    }
159→
160→    doc.Commit("marks");
161→    return doc.GetMarks(textId);
162→  }
163→}
