12→namespace Microsoft.Extensions.DependencyInjection;
13→
14→/// <summary>
15→/// Extension methods for registering server-side repo infrastructure in the DI container.
16→/// </summary>
17→[PublicAPI]
18→public static class ServerApiServiceCollectionExtensions
19→{
20→  /// <summary>
21→  /// Registers <see cref="ServerRepoManager"/>, per-app <see cref="CollaborativeHubAdapter"/>
22→  /// instances, and related services in the DI container.
23→  /// </summary>
24→  /// <param name="services">The service collection.</param>
25→  /// <param name="configureOptions">Optional action to configure <see cref="ServerRepoOptions"/>.</param>
26→  /// <returns>The service collection for chaining.</returns>
27→  public static IServiceCollection AddServerRepoManager(
28→    this IServiceCollection services,
29→    Action<ServerRepoOptions>? configureOptions = null)
30→  {
31→    ArgumentNullException.ThrowIfNull(services);
32→
33→    // Configure options
34→    if(configureOptions is not null)
35→    {
36→      services.Configure(configureOptions);
37→    }
38→    else
39→    {
40→      services.AddOptions<ServerRepoOptions>();
41→    }
42→
43→    // Register per-app adapter factory (creates one adapter per app type)
44→    services.AddSingleton<CollaborativeHubAdapterFactory>();
45→
46→    // Legacy: Register SignalRServerNetworkAdapter for backward compat with /hubs/documents
47→    services.AddSingleton<SignalRServerNetworkAdapter>(sp =>
48→    {
49→      var hubContext = sp.GetRequiredService<IHubContext<DocumentsHub, IDocumentsHubClient>>();
50→      var loggerFactory = sp.GetRequiredService<ILoggerFactory>();
51→      return new SignalRServerNetworkAdapter(hubContext, loggerFactory);
52→    });
53→
54→    // Legacy: Register hub filter to intercept DocumentsHub events
55→    services.AddSingleton<ServerDocumentsHubFilter>();
56→    services.AddSingleton<IHubFilter>(sp => sp.GetRequiredService<ServerDocumentsHubFilter>());
57→
58→    // Register ServerRepoManager wired to per-app adapters from the factory
59→    services.AddSingleton<ServerRepoManager>(sp =>
60→    {
61→      var options = sp.GetRequiredService<IOptions<ServerRepoOptions>>();
62→      var loggerFactory = sp.GetRequiredService<ILoggerFactory>();
63→      var adapterFactory = sp.GetRequiredService<CollaborativeHubAdapterFactory>();
64→
65→      return new ServerRepoManager(options, loggerFactory, appType => adapterFactory.GetOrCreate(appType));
66→    });
67→
68→    // Register as IHostedService so the host calls StartAsync/StopAsync
69→    services.AddSingleton<IHostedService>(sp => sp.GetRequiredService<ServerRepoManager>());
70→
71→    return services;
72→  }
73→}
