  3→using System.Collections.Concurrent;
  4→using Microsoft.AspNetCore.SignalR;
  5→using Microsoft.Extensions.Logging;
  6→
  7→namespace Server.Api.Hubs;
  8→
  9→/// <summary>
 10→/// Creates and caches <see cref="CollaborativeHubAdapter"/> instances per app type.
 11→/// Each adapter is wired to send messages through the correct hub's client proxy.
 12→/// </summary>
 13→/// <remarks>
 14→/// Also serves as the <see cref="INetworkAdapter"/> factory for <see cref="Services.ServerRepoManager"/>,
 15→/// ensuring the Repo for each app type routes messages through the correct hub.
 16→/// </remarks>
 17→[PublicAPI]
 18→public sealed class CollaborativeHubAdapterFactory
 19→{
 20→  readonly IServiceProvider _serviceProvider;
 21→  readonly ILoggerFactory _loggerFactory;
 22→  readonly ConcurrentDictionary<string, CollaborativeHubAdapter> _adapters = new(StringComparer.OrdinalIgnoreCase);
 23→
 24→  public CollaborativeHubAdapterFactory(IServiceProvider serviceProvider, ILoggerFactory loggerFactory)
 25→  {
 26→    ArgumentNullException.ThrowIfNull(serviceProvider);
 27→    ArgumentNullException.ThrowIfNull(loggerFactory);
 28→
 29→    _serviceProvider = serviceProvider;
 30→    _loggerFactory = loggerFactory;
 31→  }
 32→
 33→  /// <summary>
 34→  /// Gets or creates an adapter for the specified app type.
 35→  /// </summary>
 36→  public CollaborativeHubAdapter GetOrCreate(string appType)
 37→  {
 38→    ArgumentException.ThrowIfNullOrWhiteSpace(appType);
 39→
 40→    return _adapters.GetOrAdd(appType, CreateAdapter);
 41→  }
 42→
 43→  CollaborativeHubAdapter CreateAdapter(string appType)
 44→  {
 45→    var groupClientFactory = ResolveGroupClientFactory(appType);
 46→    var connectionClientFactory = ResolveConnectionClientFactory(appType);
 47→    return new CollaborativeHubAdapter(appType, groupClientFactory, connectionClientFactory, _loggerFactory);
 48→  }
 49→
 50→  Func<string, ICollaborativeHubClient> ResolveGroupClientFactory(string appType)
 51→  {
 52→    // Each app type maps to a concrete hub type. The IHubContext<THub> is registered
 53→    // by AddSignalR() and available as a singleton from DI.
 54→    return appType switch
 55→    {
 56→      TextEditorHub.AppTypeId => group =>
 57→        _serviceProvider.GetRequiredService<IHubContext<TextEditorHub, ICollaborativeHubClient>>()
 58→          .Clients.Group(group),
 59→
 60→      EditorHub.AppTypeId => group =>
 61→        _serviceProvider.GetRequiredService<IHubContext<EditorHub, ICollaborativeHubClient>>()
 62→          .Clients.Group(group),
 63→
 64→      DrawingHub.AppTypeId => group =>
 65→        _serviceProvider.GetRequiredService<IHubContext<DrawingHub, ICollaborativeHubClient>>()
 66→          .Clients.Group(group),
 67→
 68→      TaskBoardHub.AppTypeId => group =>
 69→        _serviceProvider.GetRequiredService<IHubContext<TaskBoardHub, ICollaborativeHubClient>>()
 70→          .Clients.Group(group),
 71→
 72→      _ => throw new InvalidOperationException(
 73→        $"Unknown app type '{appType}'. Supported: {TextEditorHub.AppTypeId}, {EditorHub.AppTypeId}, {DrawingHub.AppTypeId}, {TaskBoardHub.AppTypeId}")
 74→    };
 75→  }
 76→
 77→  Func<string, ICollaborativeHubClient> ResolveConnectionClientFactory(string appType)
 78→  {
 79→    return appType switch
 80→    {
 81→      TextEditorHub.AppTypeId => connectionId =>
 82→        _serviceProvider.GetRequiredService<IHubContext<TextEditorHub, ICollaborativeHubClient>>()
 83→          .Clients.Client(connectionId),
 84→
 85→      EditorHub.AppTypeId => connectionId =>
 86→        _serviceProvider.GetRequiredService<IHubContext<EditorHub, ICollaborativeHubClient>>()
 87→          .Clients.Client(connectionId),
 88→
 89→      DrawingHub.AppTypeId => connectionId =>
 90→        _serviceProvider.GetRequiredService<IHubContext<DrawingHub, ICollaborativeHubClient>>()
 91→          .Clients.Client(connectionId),
 92→
 93→      TaskBoardHub.AppTypeId => connectionId =>
 94→        _serviceProvider.GetRequiredService<IHubContext<TaskBoardHub, ICollaborativeHubClient>>()
 95→          .Clients.Client(connectionId),
 96→
 97→      _ => throw new InvalidOperationException(
 98→        $"Unknown app type '{appType}'. Supported: {TextEditorHub.AppTypeId}, {EditorHub.AppTypeId}, {DrawingHub.AppTypeId}, {TaskBoardHub.AppTypeId}")
 99→    };
100→  }
101→}
