 14→public partial class MainWindow : Window
 15→{
 16→  DocumentSessionDialogViewModel? _sessionVm;
 17→  ConnectionStatusBarViewModel? _statusBarVm;
 18→
 19→  public MainWindow()
 20→  {
 21→    InitializeComponent();
 22→    Loaded += OnLoaded;
 23→  }
 24→
 25→  async void OnLoaded(object? sender, EventArgs e)
 26→  {
 27→    _sessionVm = new DocumentSessionDialogViewModel();
 28→    _sessionVm.ResultReady += OnSessionResultReady;
 29→
 30→    SessionDialog.DataContext = _sessionVm;
 31→    SessionDialog.RefreshRequested += OnRefreshRequested;
 32→
 33→    _statusBarVm = new ConnectionStatusBarViewModel();
 34→    StatusBar.DataContext = _statusBarVm;
 35→
 36→    // Track caret position changes from the TextBox
 37→    LocalEditor.PropertyChanged += (_, args) =>
 38→    {
 39→      if(args.Property == TextBox.CaretIndexProperty && DataContext is TextEditorViewModel vm)
 40→      {
 41→        vm.CursorPosition = LocalEditor.CaretIndex;
 42→      }
 43→    };
 44→
 45→    // Load stored documents, initialize connection, then fetch server documents
 46→    if(DataContext is TextEditorViewModel vm2 && vm2.RepoService is not null)
 47→    {
 48→      _sessionVm.LoadStoredDocuments(vm2.RepoService.StorageDirectory);
 49→      await vm2.RepoService.InitializeAsync();
 50→      WireConnectionEvents(vm2.RepoService);
 51→      await _sessionVm.LoadServerDocumentsAsync(vm2.RepoService);
 52→    }
 53→  }
 54→
 55→  async void OnRefreshRequested(object? sender, EventArgs e)
 56→  {
 57→    if(_sessionVm is null || DataContext is not TextEditorViewModel vm || vm.RepoService is null)
 58→    {
 59→      return;
 60→    }
 61→
 62→    await _sessionVm.LoadServerDocumentsAsync(vm.RepoService);
 63→  }
 64→
 65→  async void OnSessionResultReady(object? sender, EventArgs e)
 66→  {
 67→    if(_sessionVm?.Result is null || DataContext is not TextEditorViewModel vm)
 68→    {
 69→      return;
 70→    }
 71→
 72→    var result = _sessionVm.Result;
 73→    _sessionVm.IsLoading = true;
 74→    _sessionVm.ErrorMessage = null;
 75→
 76→    try
 77→    {
 78→      switch(result.Action)
 79→      {
 80→        case SessionAction.Create:
 81→          await HandleCreateAsync(vm);
 82→          break;
 83→        case SessionAction.Join:
 84→          await HandleJoinAsync(vm, result.DocumentId!);
 85→          break;
 86→        case SessionAction.Resume:
 87→          await HandleResumeAsync(vm, result.DocumentId!);
 88→          break;
 89→      }
 90→
 91→      await Dispatcher.UIThread.InvokeAsync(() => _sessionVm.IsLoading = false);
 92→    }
 93→    catch(OperationCanceledException)
 94→    {
 95→      await Dispatcher.UIThread.InvokeAsync(() =>
 96→      {
 97→        vm.SyncStatus = "Operation cancelled";
 98→        _sessionVm.IsLoading = false;
 99→      });
100→    }
101→    catch(TimeoutException)
102→    {
103→      await Dispatcher.UIThread.InvokeAsync(() =>
104→      {
105→        vm.SyncStatus = "Operation timed out";
106→        _sessionVm.ErrorMessage = "The operation timed out. The document may be unavailable or the server is not responding.";
107→        _sessionVm.IsLoading = false;
108→      });
109→    }
110→    catch(Exception ex)
111→    {
112→      await Dispatcher.UIThread.InvokeAsync(() =>
113→      {
114→        vm.SyncStatus = $"Error: {ex.Message}";
115→        _sessionVm.ErrorMessage = ex.Message;
116→        _sessionVm.IsLoading = false;
117→      });
118→    }
119→  }
120→
121→  async Task HandleCreateAsync(TextEditorViewModel vm)
122→  {
123→    if(vm.RepoService is null)
124→    {
125→      // Offline mode: create a standalone document
126→      var automergeService = new AutomergeService();
127→      await Dispatcher.UIThread.InvokeAsync(() => vm.SetAutomergeService(automergeService));
128→      await ShowEditorAsync(null);
129→      return;
130→    }
131→
132→    await vm.RepoService.InitializeAsync();
133→    WireConnectionEvents(vm.RepoService);
134→
135→    // Create a new document via the repo
136→    var handle = await vm.RepoService.Repo!.Create<object>();
137→
138→    // Initialize text CRDT on the document
139→    handle.Change(doc =>
140→    {
141→      doc.PutObject(doc.RootId, "content", AutomergeContainerType.Text);
142→    }, "Initialize text field");
143→
144→    var document = ((IDocHandle)handle).GetDocument()!;
145→    var automerge = AutomergeService.FromDocument(document);
146→    await Dispatcher.UIThread.InvokeAsync(() =>
147→    {
148→      vm.SetAutomergeService(automerge);
149→      vm.DocHandle = handle;
150→    });
151→
152→    await ShowEditorAsync(handle.DocumentId.ToString());
153→  }
154→
155→  async Task HandleJoinAsync(TextEditorViewModel vm, string documentId)
156→  {
157→    if(vm.RepoService is null)
158→    {
159→      await Dispatcher.UIThread.InvokeAsync(() =>
160→        _sessionVm!.ErrorMessage = "Cannot join: no server connection");
161→      return;
162→    }
163→
164→    await vm.RepoService.InitializeAsync();
165→    WireConnectionEvents(vm.RepoService);
166→
167→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Joining document...");
168→
169→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(30));
170→    if(handle is null)
171→    {
172→      await Dispatcher.UIThread.InvokeAsync(() =>
173→        _sessionVm!.ErrorMessage = "Document not found");
174→      return;
175→    }
176→
177→    await handle.WhenReadyAsync().WaitAsync(TimeSpan.FromSeconds(30));
178→
179→    var document = ((IDocHandle)handle).GetDocument()!;
180→    var automerge = AutomergeService.FromDocument(document);
181→    await Dispatcher.UIThread.InvokeAsync(() =>
182→    {
183→      vm.SetAutomergeService(automerge);
184→      vm.DocHandle = handle;
185→    });
186→
187→    await ShowEditorAsync(handle.DocumentId.ToString());
188→  }
189→
190→  async Task HandleResumeAsync(TextEditorViewModel vm, string documentId)
191→  {
192→    if(vm.RepoService is null)
193→    {
194→      await Dispatcher.UIThread.InvokeAsync(() =>
195→        _sessionVm!.ErrorMessage = "Cannot resume: no server connection");
196→      return;
197→    }
198→
199→    await vm.RepoService.InitializeAsync();
200→    WireConnectionEvents(vm.RepoService);
201→
202→    await Dispatcher.UIThread.InvokeAsync(() => vm.SyncStatus = "Resuming document...");
203→
204→    // Find will load from local storage first
205→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(10));
206→    if(handle is null)
207→    {
208→      await Dispatcher.UIThread.InvokeAsync(() =>
209→        _sessionVm!.ErrorMessage = "Document not found in storage");
210→      return;
211→    }
212→
213→    await handle.WhenReadyAsync().WaitAsync(TimeSpan.FromSeconds(30));
214→
215→    var document = ((IDocHandle)handle).GetDocument()!;
216→    var automerge = AutomergeService.FromDocument(document);
217→    await Dispatcher.UIThread.InvokeAsync(() =>
218→    {
219→      vm.SetAutomergeService(automerge);
220→      vm.DocHandle = handle;
221→    });
222→
223→    await ShowEditorAsync(handle.DocumentId.ToString());
224→  }
225→
226→  void WireConnectionEvents(RepoService repoService)
227→  {
228→    if(_statusBarVm is null)
229→    {
230→      return;
231→    }
232→
233→    _statusBarVm.PeerId = repoService.PeerId?.ToString();
234→    _statusBarVm.ServerUrl = repoService is { IsInitialized: true }
235→      ? "Connected"
236→      : "Offline";
237→
238→    // Set initial connection state (event handler below only fires on future changes)
239→    _statusBarVm.ConnectionState = repoService.ConnectionState switch
240→    {
241→      ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
242→      ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
243→      ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
244→      _ => DemoApp.Shared.ConnectionState.Disconnected
245→    };
246→
247→    repoService.ConnectionStateChanged += (_, state) =>
248→      Dispatcher.UIThread.Post(() =>
249→      {
250→        if(_statusBarVm is null)
251→        {
252→          return;
253→        }
254→
255→        _statusBarVm.ConnectionState = state switch
256→        {
257→          ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
258→          ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
259→          ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
260→          _ => DemoApp.Shared.ConnectionState.Disconnected
261→        };
262→      });
263→
264→    repoService.PeerCountChanged += (_, count) =>
265→      Dispatcher.UIThread.Post(() =>
266→      {
267→        if(_statusBarVm is not null)
268→        {
269→          _statusBarVm.PeerCount = count;
270→        }
271→      });
272→  }
273→
274→  async Task ShowEditorAsync(string? documentId)
275→  {
276→    await Dispatcher.UIThread.InvokeAsync(() =>
277→    {
278→      SessionPanel.IsVisible = false;
279→      EditorPanel.IsVisible = true;
280→
281→      if(_statusBarVm is not null)
282→      {
283→        _statusBarVm.DocumentId = documentId ?? "local";
284→      }
285→
286→      LocalEditor.Focus();
287→    });
288→  }
289→}
