118→  /// <summary>
119→  /// Sets the AutomergeService for text operations (after document is created/loaded).
120→  /// </summary>
121→  internal void SetAutomergeService(AutomergeService service)
122→  {
123→    _automergeService = service;
124→    RefreshFromDocument();
125→  }
126→
127→  internal void ApplyTextChange(string newText)
128→  {
129→    if(_automergeService is null || _docHandle is null)
130→    {
131→      return;
132→    }
133→
134→    string currentText = _automergeService.GetText();
135→
136→    // Find the difference and apply as a splice operation.
137→    // This is a simplified diff: find common prefix and suffix.
138→    int prefixLen = 0;
139→    int minLen = Math.Min(currentText.Length, newText.Length);
140→    while(prefixLen < minLen && currentText[prefixLen] == newText[prefixLen])
141→    {
142→      prefixLen++;
143→    }
144→
145→    int suffixLen = 0;
146→    int maxSuffix = minLen - prefixLen;
147→    while(suffixLen < maxSuffix
148→      && currentText[currentText.Length - 1 - suffixLen] == newText[newText.Length - 1 - suffixLen])
149→    {
150→      suffixLen++;
151→    }
152→
153→    int deleteCount = currentText.Length - prefixLen - suffixLen;
154→    string insertText = newText.Substring(prefixLen, newText.Length - prefixLen - suffixLen);
155→
156→    if(deleteCount > 0 || insertText.Length > 0)
157→    {
158→      // Save cursor position before edit for later restoration
159→      SaveCursorBeforeEdit();
160→
161→      // Use DocHandle.Change to ensure the Repo sync protocol is triggered.
162→      // This records the change in _pendingLocalChanges and fires the Changed event,
163→      // which causes the CollectionSynchronizer to generate and send sync messages.
164→      var textId = _automergeService.TextId;
165→      _docHandle.Change(
166→        doc => doc.SpliceText(textId, (ulong)prefixLen, deleteCount, insertText),
167→        $"Edit at {prefixLen}");
168→    }
169→  }
170→
171→  internal void RefreshFromDocument()
172→  {
173→    if(_automergeService is null)
174→    {
175→      return;
176→    }
177→
178→    string text = _automergeService.GetText();
179→    if(_documentText != text)
180→    {
181→      _isRemoteUpdate = true;
182→      try
183→      {
184→        _documentText = text;
185→        this.RaisePropertyChanged(nameof(DocumentText));
186→      }
187→      finally
188→      {
189→        _isRemoteUpdate = false;
190→      }
191→    }
192→  }
193→
194→  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
195→  {
196→    if(e.IsLocal)
197→    {
198→      return;
199→    }
200→
201→    _dispatcher(() =>
202→    {
203→      SaveCursorBeforeEdit();
204→      RefreshFromDocument();
205→      RestoreCursorAfterEdit();
206→    });
207→  }
208→
209→  void SaveCursorBeforeEdit()
210→  {
211→    if(_automergeService is null || _cursorPosition <= 0)
212→    {
213→      _savedCursor = null;
214→      return;
215→    }
216→
217→    try
218→    {
219→      ulong pos = (ulong)Math.Min(_cursorPosition, _automergeService.GetText().Length);
220→      if(pos > 0)
221→      {
222→        _savedCursor = _automergeService.GetCursor(pos - 1);
223→      }
224→      else
225→      {
226→        _savedCursor = null;
227→      }
228→    }
229→    catch(Exception)
230→    {
231→      _savedCursor = null;
232→    }
233→  }
234→
235→  void RestoreCursorAfterEdit()
236→  {
237→    if(_automergeService is null || _savedCursor is null)
238→    {
239→      return;
240→    }
241→
242→    try
243→    {
244→      ulong pos = _automergeService.GetCursorPosition(_savedCursor);
245→      CursorPosition = (int)(pos + 1);
246→    }
247→    catch(Exception)
248→    {
249→      // Cursor may be invalid after merge — leave at current position
250→    }
251→
252→    _savedCursor = null;
253→  }
254→
255→  void SaveDocument()
256→  {
257→    if(_automergeService is null)
258→    {
259→      SyncStatus = "No document loaded";
260→      return;
261→    }
262→
263→    byte[] saved = _automergeService.Save();
264→    SyncStatus = $"Saved ({saved.Length} bytes)";
265→  }
266→
267→  void ExportJson()
268→  {
269→    if(_automergeService is null)
270→    {
271→      SyncStatus = "No document loaded";
272→      return;
273→    }
274→
275→    string json = _automergeService.Document.HydrateJson();
276→    _logger.LogInformation("Document JSON: {Json}", json);
277→    SyncStatus = $"Exported JSON ({json.Length} chars)";
278→  }
279→
280→  public void Dispose()
281→  {
282→    if(!_disposed)
283→    {
284→      _disposed = true;
285→
286→      if(_docHandle is not null)
287→      {
288→        _docHandle.Changed -= OnDocHandleChanged;
289→      }
290→
291→      _automergeService?.Dispose();
292→      _repoService?.Dispose();
293→    }
294→  }
295→}
