  3→using Six.Automerge;
  4→
  5→namespace DemoApp.CollaborativeTextEditor.Services;
  6→
  7→/// <summary>
  8→/// Wraps <see cref="AutomergeDocument"/> to provide text CRDT operations
  9→/// for the collaborative text editor demo.
 10→/// </summary>
 11→sealed class AutomergeService : IDisposable
 12→{
 13→  readonly AutomergeDocument _document;
 14→  readonly AutomergeObjectId _textId;
 15→  readonly bool _ownsDocument;
 16→  bool _disposed;
 17→
 18→  public AutomergeService()
 19→  {
 20→    _document = AutomergeDocument.Create();
 21→    _textId = _document.PutObject(_document.RootId, "content", AutomergeContainerType.Text);
 22→    _document.Commit("Initialize text field");
 23→    _ownsDocument = true;
 24→  }
 25→
 26→  AutomergeService(AutomergeDocument document, AutomergeObjectId textId, bool ownsDocument)
 27→  {
 28→    _document = document;
 29→    _textId = textId;
 30→    _ownsDocument = ownsDocument;
 31→  }
 32→
 33→  /// <summary>
 34→  /// Gets the underlying document for sync operations.
 35→  /// </summary>
 36→  public AutomergeDocument Document => _document;
 37→
 38→  /// <summary>
 39→  /// Gets the text object identifier for cursor operations.
 40→  /// </summary>
 41→  public AutomergeObjectId TextId => _textId;
 42→
 43→  /// <summary>
 44→  /// Gets the current text content of the document.
 45→  /// </summary>
 46→  public string GetText()
 47→  {
 48→    ThrowIfDisposed();
 49→    return _document.GetText(_textId);
 50→  }
 51→
 52→  /// <summary>
 53→  /// Splices text at the given position: deletes <paramref name="deleteCount"/> characters
 54→  /// and inserts <paramref name="insertText"/> at <paramref name="index"/>.
 55→  /// </summary>
 56→  public void SpliceText(ulong index, long deleteCount, string insertText)
 57→  {
 58→    ThrowIfDisposed();
 59→    _document.SpliceText(_textId, index, deleteCount, insertText);
 60→    _document.Commit($"Edit at {index}");
 61→  }
 62→
 63→  /// <summary>
 64→  /// Gets a stable cursor at the given index. Cursors track logical positions
 65→  /// even as concurrent edits shift indices.
 66→  /// </summary>
 67→  public AutomergeCursor GetCursor(ulong index)
 68→  {
 69→    ThrowIfDisposed();
 70→    return _document.GetCursor(_textId, index);
 71→  }
 72→
 73→  /// <summary>
 74→  /// Resolves a cursor to its current index position.
 75→  /// </summary>
 76→  public ulong GetCursorPosition(AutomergeCursor cursor)
 77→  {
 78→    ThrowIfDisposed();
 79→    return _document.GetCursorPosition(_textId, cursor);
 80→  }
 81→
 82→  /// <summary>
 83→  /// Saves the full document state as a byte array.
 84→  /// </summary>
 85→  public byte[] Save()
 86→  {
 87→    ThrowIfDisposed();
 88→    return _document.Save();
 89→  }
 90→
 91→  /// <summary>
 92→  /// Creates an AutomergeService that wraps an existing document, initializing the text field
 93→  /// if it doesn't already exist. The document is NOT owned (not disposed by this service).
 94→  /// </summary>
 95→  public static AutomergeService FromDocument(AutomergeDocument document)
 96→  {
 97→    ArgumentNullException.ThrowIfNull(document);
 98→
 99→    var keys = document.GetKeys(document.RootId).ToList();
100→    AutomergeObjectId textId;
101→
102→    if(keys.Contains("content"))
103→    {
104→      textId = document.GetObject(document.RootId, "content")
105→        ?? throw new InvalidOperationException("Could not resolve 'content' text object.");
106→    }
107→    else
108→    {
109→      textId = document.PutObject(document.RootId, "content", AutomergeContainerType.Text);
110→      document.Commit("Initialize text field");
111→    }
112→
113→    return new AutomergeService(document, textId, ownsDocument: false);
114→  }
115→
116→  /// <summary>
117→  /// Loads a document from a previously saved byte array.
118→  /// </summary>
119→  public static AutomergeService Load(byte[] data)
120→  {
121→    var doc = AutomergeDocument.Load(data);
122→    var keys = doc.GetKeys(doc.RootId).ToList();
123→    if(!keys.Contains("content"))
124→    {
125→      throw new InvalidOperationException("Saved document does not contain a 'content' text field.");
126→    }
127→
128→    var textId = doc.GetObject(doc.RootId, "content")
129→      ?? throw new InvalidOperationException("Could not resolve 'content' text object.");
130→
131→    return new AutomergeService(doc, textId, ownsDocument: true);
132→  }
133→
134→  public void Dispose()
135→  {
136→    if(!_disposed)
137→    {
138→      _disposed = true;
139→      if(_ownsDocument)
140→      {
141→        _document.Dispose();
142→      }
143→    }
144→  }
145→
146→  void ThrowIfDisposed()
147→  {
148→    ObjectDisposedException.ThrowIf(_disposed, this);
149→  }
150→}
